import { createAuth, createAuthorizer } from '@cossackframework/auth';
import { Hono } from 'hono';
import { getCookie } from 'hono/cookie';

interface User { id: string; roles: readonly string[] }
// Fixed fixtures for this executable test. Replace them with trusted session storage.
const auth = createAuth<User>({
  extractSessionId: c => getCookie(c, 'session_id'),
  validateSessionId: async id => id === 'fixture-session' ? 'owner' : null,
  resolveUserById: async id => id === 'owner' ? { id, roles: ['editor'] } : null,
});
const guard = createAuthorizer<User>({ hasRole: (user, role) => user.roles.includes(role) });
const app = new Hono<{ Variables: { user?: User } }>();
app.use('*', auth.middleware);
app.get('/editor', guard.requireRole('editor'), c => c.json({ id: c.get('user')!.id }));
app.get('/any', guard.requireRole('editor', 'admin'), c => c.text('allowed'));
app.get('/all', guard.requireAllRoles('editor', 'admin'), c => c.text('allowed'));

const anonymous = await app.request('/editor');
if (anonymous.status !== 401) throw new Error('An anonymous user must not enter the editor route');
const forged = await app.request('/editor', { headers: { Cookie: 'session_id=claimed-admin' } });
if (forged.status !== 401) throw new Error('A claimed session must pass trusted validation');
const options = { headers: { Cookie: 'session_id=fixture-session' } };
const editor = await app.request('/editor', options);
if (editor.status !== 200 || (await editor.json()).id !== 'owner') throw new Error('A validated editor session must resolve its user');
if ((await app.request('/any', options)).status !== 200) throw new Error('Any-role guards use OR semantics');
if ((await app.request('/all', options)).status !== 403) throw new Error('All-role guards require every role');

import { createResourcePolicy, ResourceAuthorizationError } from '@cossackframework/auth';
import { Hono, type Context } from 'hono';

interface User { id: string; tenant: string }
interface Post { id: number; owner: string; tenant: string }
const posts = createResourcePolicy<Post, User>()({
  read: ({ user, resource }) => user.tenant === resource.tenant,
  edit: ({ user, resource }) => user.id === resource.owner && user.tenant === resource.tenant,
});
const record: Post = { id: 1, owner: 'owner', tenant: 'team' };
async function fixtureContext(user: User | undefined): Promise<Context> {
  let context!: Context;
  const app = new Hono<{ Variables: { user: User | undefined } }>();
  app.get('/', c => { c.set('user', user); context = c; return new Response(null); });
  await app.fetch(new Request('https://fixture.invalid/'));
  return context;
}
const owner = await fixtureContext({ id: 'owner', tenant: 'team' });
if (await posts.authorize(owner, 'edit', record) !== record) throw new Error('The owner must receive the accepted record');
const viewer = await fixtureContext({ id: 'viewer', tenant: 'team' });
const permissions = await posts.permissions(viewer, record);
if (!Object.isFrozen(permissions) || !permissions.read || permissions.edit) throw new Error('Presentation permissions must reflect actual record decisions');
for (const [context, code] of [
  [viewer, 'COSSACK_AUTH_FORBIDDEN'],
  [await fixtureContext(undefined), 'COSSACK_AUTH_UNAUTHENTICATED'],
] as const) {
  let denied = false;
  try { await posts.authorize(context, 'edit', record); }
  catch (error) {
    if (!(error instanceof ResourceAuthorizationError) || error.authorizationCode !== code) throw error;
    denied = true;
  }
  if (!denied) throw new Error('Denied actors must not receive an accepted record');
}
const gate = posts.action('edit', (data: { id: number }, { context, signal }) => {
  if (context !== owner || signal.aborted) throw new Error('Lookup lost its trusted ownership context');
  return data.id === record.id ? record : undefined;
});
if (!await gate({ id: 1 }, { context: owner, signal: owner.req.raw.signal })) throw new Error('The action gate must allow the owned record');
let missing = false;
try { await gate({ id: 2 }, { context: owner, signal: owner.req.raw.signal }); }
catch (error) {
  if (!(error instanceof ResourceAuthorizationError) || error.authorizationCode !== 'COSSACK_AUTH_FORBIDDEN') throw error;
  missing = true;
}
if (!missing) throw new Error('Missing records must be denied');

import { createOAuth, OAuthError } from '@cossackframework/auth';
import { Hono } from 'hono';

const oauth = createOAuth({
  secret: 'fixture-state-secret-01234567890123456789',
  providers: { github: { clientId: 'fixture-id', clientSecret: 'fixture-secret', redirectUrl: '/callback' } },
});
const app = new Hono();
const seen: { failure?: OAuthError } = {};
app.get('/callback', oauth.callback('github', {
  onUser: () => { throw new Error('This failure example must not map an account'); },
  onError: (error, context) => {
    seen.failure = error;
    return context.json(error.toJSON(), error.status);
  },
}));
const denied = await app.request('/callback?error=access_denied&error_description=UNTRUSTED_DESCRIPTION');
if (denied.status !== 403 || !seen.failure || seen.failure.code !== 'COSSACK_OAUTH_CONSENT_DENIED') throw new Error('Consent denial lost its diagnostic');
if (!Object.isFrozen(seen.failure) || seen.failure.cause !== undefined) throw new Error('The error must contain only immutable library diagnostics');
if ((await denied.text()).includes('UNTRUSTED_DESCRIPTION')) throw new Error('Provider descriptions must not be echoed');
if (!denied.headers.get('set-cookie')?.includes('Max-Age=0')) throw new Error('A rejected callback must clear its state cookie');
const malformed = await app.request('/callback');
if (malformed.status !== 400 || (await malformed.json()).stage !== 'callback') throw new Error('Malformed callbacks must identify the callback stage');
